import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import java.math.BigDecimal;

@Component
@RequiredArgsConstructor
@Slf4j
public class TransferNotifier {

    // No @Qualifier → Spring injects the @Primary bean (EmailNotificationService)
    private final NotificationService notificationService;

    public void notifyTransfer(String fromId, String toId, BigDecimal amount) {
        log.info("TransferNotifier using: {} (@Primary)", notificationService.getChannelName());
        notificationService.send(fromId,
            "Transfer Confirmation",
            "Rs." + amount + " transferred to " + toId);
    }
}
