package com.bank.notification.consumer;

import com.bank.notification.service.NotificationService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Component;

@Component
@Slf4j
public class FraudAlertNotifier {

    private final NotificationService smsNotifier;

    // @Qualifier overrides @Primary — explicitly picks SMS
    public FraudAlertNotifier(@Qualifier("smsNotificationService") NotificationService smsNotifier) {
        this.smsNotifier = smsNotifier;
        log.info("FraudAlertNotifier using: {} (@Qualifier)", smsNotifier.getChannelName());
    }

    public void alertFraud(String accountId, String tradeId) {
        smsNotifier.send(accountId,
            "FRAUD ALERT",
            "URGENT: Suspicious activity on trade " + tradeId + ". Call 1800-BANK immediately.");
    }
}
