// Uses List<NotificationService> — gets ALL channels for broadcast
package com.bank.notification.consumer;

import com.bank.notification.service.NotificationService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import java.util.List;

@Component
@Slf4j
public class MarketingBroadcaster {

    // List injection: Spring injects ALL NotificationService beans
    private final List<NotificationService> allChannels;

    public MarketingBroadcaster(List<NotificationService> allChannels) {
        this.allChannels = allChannels;
        log.info("MarketingBroadcaster using ALL {} channels: {}",
            allChannels.size(),
            allChannels.stream().map(NotificationService::getChannelName).toList());
    }

    public void broadcast(String subject, String message) {
        log.info("Broadcasting to ALL channels: {}", subject);
        allChannels.forEach(channel -> channel.send("ALL_CUSTOMERS", subject, message));
    }
}
