// Uses Map<String, NotificationService> — picks channel at RUNTIME based on DB preference
package com.bank.notification.consumer;

import com.bank.notification.service.NotificationService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import java.util.Map;

@Component
@Slf4j
public class CustomerPreferenceNotifier {

    // Map injection: keys = bean names, values = bean instances
    private final Map<String, NotificationService> channelMap;

    public CustomerPreferenceNotifier(Map<String, NotificationService> channelMap) {
        this.channelMap = channelMap;
        log.info("CustomerPreferenceNotifier loaded {} channels: {}",
            channelMap.size(), channelMap.keySet());
    }

    /**
     * Sends notification via the customer's PREFERRED channel (from DB).
     * @param preferredChannel bean name like "smsNotificationService"
     */
    public void sendViaPreference(String accountId, String preferredChannel,
                                   String subject, String message) {
        NotificationService channel = channelMap.get(preferredChannel);
        if (channel == null) {
            log.warn("Unknown channel '{}' for {}. Falling back to email.", preferredChannel, accountId);
            channel = channelMap.get("emailNotificationService");
        }
        log.info("Sending via {} (customer preference)", channel.getChannelName());
        channel.send(accountId, subject, message);
    }
}
