@Component("stripe")  class StripeGateway implements PaymentGateway {}
@Primary                                           // default choice
@Component("adyen")   class AdyenGateway  implements PaymentGateway {}
@Component("paypal")  class PayPalGateway implements PaymentGateway {}

@Service
class CheckoutService {
  // @Primary resolves the ambiguity → AdyenGateway injected
  private final PaymentGateway defaultGateway;

  // @Qualifier selects a specific bean by name
  @Qualifier("stripe")
  private final PaymentGateway premiumGateway;

  // inject ALL implementations keyed by bean name (strategy pattern)
  private final Map<String, PaymentGateway> gateways;

  CheckoutService(PaymentGateway defaultGateway,
                  @Qualifier("stripe") PaymentGateway premiumGateway,
                  Map<String,PaymentGateway> gateways){ ... }

  PaymentResult pay(Order o){
    PaymentGateway g = gateways.getOrDefault(o.region(), defaultGateway);
    return g.charge(o.total());
  }
}
